function decodeBase64(value: string): Uint8Array {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

async function gunzipBase64(value: string): Promise<Uint8Array> {
  const compressed = decodeBase64(value);
  const compressedBuffer = new ArrayBuffer(compressed.byteLength);
  new Uint8Array(compressedBuffer).set(compressed);
  const stream = new Blob([compressedBuffer])
    .stream()
    .pipeThrough(new DecompressionStream("gzip"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

let cachedFonts: Promise<{ regular: Uint8Array; bold: Uint8Array }> | undefined;

export function loadEmbeddedRobotoFonts(): Promise<{
  regular: Uint8Array;
  bold: Uint8Array;
}> {
  cachedFonts ??= Promise.all([
    gunzipBase64(ROBOTO_REGULAR_GZIP_BASE64),
    gunzipBase64(ROBOTO_BOLD_GZIP_BASE64),
  ]).then(([regular, bold]) => ({ regular, bold }));
  return cachedFonts;
}
